import { readFile, readdir, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { rules } from '../src/rules/index.js';
import { resolveRuleSeverity, type RuleWithDocs } from '../src/rules/types.js';

const CORE_CATEGORY = 'core';

const GENERATED_HEADER =
  '<!-- Generated by `npm run docs:rules`. Do not edit by hand. -->';

const CHECK_MARK = '✔';

const DOCS_RULES_DIR = 'docs/rules';

/** The wasm-free rule barrel this script reads metadata from. */
const RULE_BARREL = 'src/rules/index.ts';

/** `docs/` is the vitepress source root, so rule pages route under `/rules`. */
const DOCS_RULES_DIR_ROUTE = 'rules';

/** Generated by this script, so it is not a rule page and has no rule. */
const RULE_INDEX_PAGE = 'index';

const RULE_INDEX_SIDEBAR_TEXT = 'All rules';

const MARKDOWN_EXTENSION = '.md';

interface RuleIndexColumn {
  header: string;
  cell: (entry: RuleIndexEntry) => string;
}

/**
 * The single declaration of the index table. The header row, the separator
 * row, and every rule row are all derived from this, so a column cannot be
 * added or reordered in one place and forgotten in another.
 */
const TABLE_COLUMNS: readonly RuleIndexColumn[] = [
  {
    header: 'Rule',
    cell: (entry) =>
      `[\`${entry.name}\`](./${entry.name}${MARKDOWN_EXTENSION})`,
  },
  {
    header: 'Description',
    cell: (entry) => escapeTableCell(entry.description),
  },
  { header: 'Severity', cell: (entry) => entry.severity },
  { header: 'Category', cell: (entry) => entry.category },
  { header: 'Recommended', cell: (entry) => flag(entry.recommended) },
  { header: 'Fixable', cell: (entry) => flag(entry.fixable) },
];

function flag(on: boolean): string {
  return on ? CHECK_MARK : '';
}

export interface RuleIndexEntry {
  name: string;
  description: string;
  severity: 'error' | 'warn';
  category: string;
  recommended: boolean;
  fixable: boolean;
}

export interface RuleCategoryGroup {
  category: string;
  entries: RuleIndexEntry[];
}

export interface RuleDocsPage {
  name: string;
  firstLine: string;
}

export interface RuleSidebarLink {
  text: string;
  link: string;
}

export interface RuleSidebarGroup {
  text: string;
  items: RuleSidebarLink[];
}

export type RuleSidebarEntry = RuleSidebarLink | RuleSidebarGroup;

export function toRuleIndexEntries(
  ruleMap: Record<string, RuleWithDocs>,
): RuleIndexEntry[] {
  const entries: RuleIndexEntry[] = [];
  for (const [name, rule] of Object.entries(ruleMap)) {
    const docs = rule.meta?.docs;
    entries.push({
      name,
      description: docs?.description ?? '',
      severity: resolveRuleSeverity(docs),
      category: docs?.category ?? CORE_CATEGORY,
      recommended: docs?.recommended === true,
      fixable: rule.meta?.fixable !== undefined,
    });
  }
  return entries;
}

export function groupRulesByCategory(
  entries: readonly RuleIndexEntry[],
): RuleCategoryGroup[] {
  const byCategory = new Map<string, RuleIndexEntry[]>();
  for (const entry of entries) {
    const group = byCategory.get(entry.category);
    if (group) {
      group.push(entry);
    } else {
      byCategory.set(entry.category, [entry]);
    }
  }
  return [...byCategory]
    .map(([category, groupEntries]) => ({
      category,
      entries: [...groupEntries].sort((a, b) => a.name.localeCompare(b.name)),
    }))
    .sort((a, b) => compareCategories(a.category, b.category));
}

export function renderRuleIndex(entries: readonly RuleIndexEntry[]): string {
  const sections = groupRulesByCategory(entries).map((group) =>
    [
      `## ${group.category}`,
      '',
      renderRow(TABLE_COLUMNS.map((column) => column.header)),
      renderRow(TABLE_COLUMNS.map(() => '---')),
      ...group.entries.map(renderRuleRow),
      '',
    ].join('\n'),
  );
  return [GENERATED_HEADER, '', '# Rules', '', ...sections].join('\n');
}

function renderRuleRow(entry: RuleIndexEntry): string {
  return renderRow(TABLE_COLUMNS.map((column) => column.cell(entry)));
}

function renderRow(cells: readonly string[]): string {
  return `| ${cells.join(' | ')} |`;
}

function escapeTableCell(text: string): string {
  return text.replaceAll('|', '\\|');
}

export function findRuleDocsParityProblems(
  ruleNames: readonly string[],
  docsPageNames: readonly string[],
): string[] {
  const pages = new Set(docsPageNames);
  const names = new Set(ruleNames);
  const missingPages = ruleNames
    .filter((name) => !pages.has(name))
    .map(
      (name) =>
        `rule "${name}" has no docs page. expected ${DOCS_RULES_DIR}/${name}${MARKDOWN_EXTENSION}`,
    );
  const orphanPages = docsPageNames
    .filter((page) => page !== RULE_INDEX_PAGE && !names.has(page))
    .map(
      (page) =>
        `${DOCS_RULES_DIR}/${page}${MARKDOWN_EXTENSION} has no matching rule in ${RULE_BARREL}`,
    );
  return [...missingPages, ...orphanPages];
}

export function findRuleDescriptionProblems(
  entries: readonly RuleIndexEntry[],
): string[] {
  return entries
    .filter((entry) => entry.description.trim() === '')
    .map(
      (entry) =>
        `rule "${entry.name}" has an empty meta.docs.description. every rule in ${RULE_BARREL} must describe what it enforces`,
    );
}

export function buildRuleSidebar(
  entries: readonly RuleIndexEntry[],
): RuleSidebarEntry[] {
  return [
    { text: RULE_INDEX_SIDEBAR_TEXT, link: `/${DOCS_RULES_DIR_ROUTE}/` },
    ...groupRulesByCategory(entries).map((group) => ({
      text: group.category,
      items: group.entries.map((entry) => ({
        text: entry.name,
        link: `/${DOCS_RULES_DIR_ROUTE}/${entry.name}`,
      })),
    })),
  ];
}

export function findRuleDocsHeadingProblems(
  pages: readonly RuleDocsPage[],
): string[] {
  return pages
    .filter(
      (page) =>
        page.name !== RULE_INDEX_PAGE && page.firstLine !== `# ${page.name}`,
    )
    .map(
      (page) =>
        `${DOCS_RULES_DIR}/${page.name}${MARKDOWN_EXTENSION} opens with "${page.firstLine}", expected "# ${page.name}"`,
    );
}

/**
 * Every invariant the generated index depends on, in one pass: a rule with no
 * docs page, a docs page with no rule, a page heading that disagrees with its
 * filename, and a rule with no description.
 */
export function findRuleIndexProblems(
  entries: readonly RuleIndexEntry[],
  pages: readonly RuleDocsPage[],
): string[] {
  return [
    ...findRuleDocsParityProblems(
      entries.map((entry) => entry.name),
      pages.map((page) => page.name),
    ),
    ...findRuleDocsHeadingProblems(pages),
    ...findRuleDescriptionProblems(entries),
  ];
}

function compareCategories(a: string, b: string): number {
  if (a === b) return 0;
  if (a === CORE_CATEGORY) return -1;
  if (b === CORE_CATEGORY) return 1;
  return a.localeCompare(b);
}

async function readRuleDocsPages(pagesDir: string): Promise<RuleDocsPage[]> {
  const files = (await readdir(pagesDir)).filter((file) =>
    file.endsWith(MARKDOWN_EXTENSION),
  );
  return Promise.all(
    files.map(async (file) => ({
      name: file.slice(0, -MARKDOWN_EXTENSION.length),
      firstLine:
        (await readFile(join(pagesDir, file), 'utf8')).split('\n')[0] ?? '',
    })),
  );
}

function isFileNotFound(error: unknown): boolean {
  return error instanceof Error && 'code' in error && error.code === 'ENOENT';
}

/** The index as it sits on disk, or `undefined` when it does not exist yet. */
async function readIndexIfPresent(path: string): Promise<string | undefined> {
  try {
    return await readFile(path, 'utf8');
  } catch (error) {
    if (isFileNotFound(error)) return undefined;
    throw error;
  }
}

export interface IndexOutcomeInput {
  rendered: string;
  /** The index on disk, or `undefined` when it does not exist yet. */
  current: string | undefined;
  checkMode: boolean;
  hasProblems: boolean;
}

export interface IndexOutcome {
  write: boolean;
  reportStale: boolean;
  exitCode: 0 | 1;
}

/**
 * Whether to write the index and what to exit with. Pure, so the rule that
 * matters here is testable without touching the filesystem.
 *
 * Validation and generation are deliberately independent. A parity problem
 * must not stop the write: `npm run docs:rules` is the fix the stale-index
 * message and the generated header both point at, so it has to regenerate in
 * exactly the situation that sends someone there. Problems still fail the run,
 * and `--check` never writes.
 */
export function decideIndexOutcome({
  rendered,
  current,
  checkMode,
  hasProblems,
}: IndexOutcomeInput): IndexOutcome {
  const stale = rendered !== current;
  if (checkMode) {
    return {
      write: false,
      reportStale: stale,
      exitCode: stale || hasProblems ? 1 : 0,
    };
  }
  return {
    write: stale,
    reportStale: false,
    exitCode: hasProblems ? 1 : 0,
  };
}

async function main(): Promise<number> {
  const root = join(dirname(fileURLToPath(import.meta.url)), '..');
  const pagesDir = join(root, DOCS_RULES_DIR);
  const indexPath = join(pagesDir, `${RULE_INDEX_PAGE}${MARKDOWN_EXTENSION}`);
  const checkMode = process.argv.includes('--check');

  const entries = toRuleIndexEntries(rules);
  const pages = await readRuleDocsPages(pagesDir);

  const problems = findRuleIndexProblems(entries, pages);
  for (const problem of problems) {
    console.error(problem);
  }

  const rendered = renderRuleIndex(entries);
  const outcome = decideIndexOutcome({
    rendered,
    current: await readIndexIfPresent(indexPath),
    checkMode,
    hasProblems: problems.length > 0,
  });

  if (outcome.reportStale) {
    console.error(
      `${DOCS_RULES_DIR}/${RULE_INDEX_PAGE}${MARKDOWN_EXTENSION} is stale. run: npm run docs:rules`,
    );
  }
  if (outcome.write) {
    await writeFile(indexPath, rendered);
  }
  return outcome.exitCode;
}

const entryPoint = process.argv[1];
const isMain =
  entryPoint !== undefined &&
  import.meta.url === pathToFileURL(entryPoint).href;

if (isMain) {
  process.exit(await main());
}
